\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Draw grid
    \draw[help lines, lightgray, step=0.5cm] (0,-1.5) grid (7,1.5);

    % Axis
    \draw[->, thick] (0,0) -- (7.5,0) node[right] {distance / m};
    \draw[->, thick] (0,-1.5) -- (0,1.5) node[above] {displacement};

    % Tick marks and labels for distance (0 to 0.7 m mapped to 0 to 7 cm)
    \foreach \x/\val in {0/0, 1/0.1, 2/0.2, 3/0.3, 4/0.4, 5/0.5, 6/0.6, 7/0.7} {
        \draw (\x, 0.1) -- (\x, -0.1) node[below=2pt] {\val};
    }

    % Displacement zero label
    \node[left] at (0,0) {$0$};

    % Sine wave: Wavelength = 0.4 m (4 cm on graph)
    % y = A * sin(2*pi*x / lambda) -> y = sin(2*pi*x / 4)
    % Amplitude let's set to 1 cm (which corresponds to some value on graph)
    \draw[thick, domain=0:7, samples=100] plot (\x, {1 * sin(\x * 90)});

    % Points A and B
    % A is at 0.25 m (2.5 cm) where displacement is zero (crossing down: at x=2.5, sin(2.5*90) = sin(225) = -0.7, wait)
    % Let's check the prompt: "It crosses zero going down at 0.25 m"
    % Equation for standard sine starting at 0: y = sin(2*pi*x / 0.4) = sin(360 * x / 0.4) = sin(900 * x)
    % At x = 0.25: sin(900 * 0.25) = sin(225°) = -0.707 (crosses zero going DOWN? sin(180)=0, sin(270)=-1. Wait, at x=0.2, sin(180)=0 going down? 
    % Let's trace carefully:
    % x=0, y=0, going UP to crest at x=0.1 (sin(90)=1)
    % x=0.2, y=0, going DOWN to trough at x=0.3 (sin(270)=-1)
    % x=0.4, y=0, going UP
    % Prompt says: "crosses zero going down at 0.25 m" -> Ah, let's adjust the sine wave phase or match the prompt's exact words.
    % Prompt: "crosses zero going down at 0.25 m, and has crests at 0.15 m and 0.55 m."
    % Let's use phase shift: wave with crest at 0.15 m and wavelength 0.4 m.
    % y = cos(2*pi*(x - 0.15)/0.4) = cos(360*(x - 0.15)/0.4) = cos(900*(x - 0.15))
    % Let's check crest at x = 0.15: cos(0) = 1. Correct.
    % Next crest at x = 0.15 + 0.4 = 0.55: cos(360) = 1. Correct.
    % Does it cross zero going down at 0.25 m?
    % At x = 0.25: 900*(0.25 - 0.15) = 900*0.10 = 90°. cos(90°) = 0. 
    % Derivative at x = 0.25: -900 * sin(90°) = -900 (negative, so going down!). Perfect!

    % Let's redraw the plot using this exact function: y = 1 * cos(900*(x - 0.15)) converted to degrees:
    % Note: TikSin/Cos uses degrees. 900*(x-0.15) radians? No, 900 degrees per meter? 
    % Let's use standard trigonometric expression with radians or proper degree scaling.
    % 360 degrees = 0.4 m -> 1 m = 900 degrees.
    % So angle in degrees = \x * 900 - 135 (since 0.15 * 900 = 135°).
    % Let's test:
    % x = 0.15 -> 0.15*900 - 135 = 0°. cos(0) = 1 (crest).
    % x = 0.25 -> 0.25*900 - 135 = 225 - 135 = 90°. cos(90) = 0 (crossing down? wait, cos goes from 1 to 0 at 90, then to -1 at 180. So at 90 it's going down towards -1. Yes!).
    % Let's check x = 0.25 -> angle = 90°. 
    % Let's plot using evaluated formula:
    \def\mywave{1 * cos(\x * 900 - 135)}

    % Redraw wave cleanly with correct function
    \undo{\draw}
    \draw[thick, domain=0:7, samples=200] plot (\x, {\mywave});

    % Point A: at x = 0.25 m (2.5 cm on graph), displacement = 0
    \coordinate (A) at (2.5, {1 * cos(2.5 * 900 - 135)});
    \fill (A) circle (2pt);
    \node[above right] at (A) {A};

    % Point B: "at 0.5 m, on the rising part before the crest."
    % Let's check x = 0.5 m (5 cm on graph):
    % angle = 5 * 900 - 135 = 4500 - 135 = 4365 = 4365 - 360*12 = 4365 - 4320 = 45°.
    % cos(45°) = 0.707 (positive, on the rising part before the crest at 0.55).
    \coordinate (B) at (5, {1 * cos(5 * 900 - 135)});
    \fill (B) circle (2pt);
    \node[above left] at (B) {B};

    % Direction of travel arrow above the graph
    \draw[-{Stealth}, thick] (3, 1.8) -- (5, 1.8);
    \node[above] at (4, 1.8) {\small direction of travel of the wave};

    % Caption below
    \node[below=1cm] at (3.5,-1.5) {Fig. 9.1};

\end{tikzpicture}

