\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Draw grid
    \draw[help lines, lightgray, step=0.5cm] (0,-1.5) grid (7,1.5);

    % Axis
    \draw[->, thick] (0,0) -- (7.5,0) node[right] {distance / m};
    \draw[->, thick] (0,-1.5) -- (0,1.5) node[above] {displacement};

    % Tick marks and labels for distance (0 to 0.7 m mapped to 0 to 7 cm)
    \foreach \x/\val in {0/0, 1/0.1, 2/0.2, 3/0.3, 4/0.4, 5/0.5, 6/0.6, 7/0.7} {
        \draw (\x, 0.1) -- (\x, -0.1) node[below=2pt] {\val};
    }

    % Displacement zero label
    \node[left] at (0,0) {$0$};

    % Sine wave formula:
    % Wavelength = 0.4 m -> 0.4 m corresponds to 4 cm (4 units on x-axis).
    % Therefore, 1 cm on graph = 0.1 m in distance.
    % To get wavelength = 0.4 m, frequency factor is 360 degrees per 4 cm = 90 degrees per cm.
    % We need:
    % - Crests at 0.15 m and 0.55 m (1.5 cm and 5.5 cm)
    % - Crosses zero going down at 0.25 m (2.5 cm)
    % Let's use cosine with phase shift: cos((x - 1.5) * 90) = cos(90*x - 135)
    % Let's check at x = 2.5 cm (0.25 m): cos(90*2.5 - 135) = cos(90) = 0.
    % Derivative at x = 2.5: -90 * sin(90) = -90 (negative, so crossing zero going DOWN). Perfect!
    \def\mywave{1 * cos(\x * 90 - 135)}

    % Draw wave
    \draw[thick, domain=0:7, samples=200] plot (\x, {\mywave});

    % Point A: at x = 0.25 m (2.5 cm on graph), displacement = 0
    \coordinate (A) at (2.5, 0);
    \fill (A) circle (2pt);
    \node[above right] at (A) {A};

    % Point B: at 0.5 m (5 cm on graph), on the rising part before the crest (crest is at 0.55 m = 5.5 cm)
    % At x = 5 cm (0.5 m): cos(5 * 90 - 135) = cos(315) = 0.707 (rising towards crest at 5.5 cm where cos(360) = 1)
    \coordinate (B) at (5, {1 * cos(5 * 90 - 135)});
    \fill (B) circle (2pt);
    \node[above left] at (B) {B};

    % Direction of travel arrow above the graph
    \draw[-{Stealth}, thick] (2.5, 1.8) -- (4.5, 1.8);
    \node[above] at (3.5, 1.8) {\small direction of travel of the wave};

    % Caption below
    \node[below=1cm] at (3.5,-1.5) {Fig. 9.1};

\end{tikzpicture}
